import{_ as o,o as s,c as e,ag as n}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-13（量子物理）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/quantum-physics/science-daily-2026-10-13.md","filePath":"topics/quantum-physics/science-daily-2026-10-13.md"}'),r={name:"topics/quantum-physics/science-daily-2026-10-13.md"};function c(i,t,a,d,l,u){return s(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="科学日报-·-2026-10-13-量子物理" tabindex="-1">科学日报 · 2026-10-13（量子物理） <a class="header-anchor" href="#科学日报-·-2026-10-13-量子物理" aria-label="Permalink to &quot;科学日报 · 2026-10-13（量子物理）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-13.md</code> — 第36期 ｜ 科学板块</p></blockquote><hr><h2 id="芯片上的光子量子斯格明子-拓扑比纠缠更抗噪-nature-physics" tabindex="-1">芯片上的光子量子斯格明子：拓扑比纠缠更抗噪（Nature Physics） <a class="header-anchor" href="#芯片上的光子量子斯格明子-拓扑比纠缠更抗噪-nature-physics" aria-label="Permalink to &quot;芯片上的光子量子斯格明子：拓扑比纠缠更抗噪（Nature Physics）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-13.md</code> ｜ DOI: 10.1038/s41567-026-03487-x</p></blockquote><ul><li>背景：<strong>量子斯格明子</strong>因<strong>拓扑鲁棒性</strong>受到关注，为量子系统的<strong>噪声与损耗</strong>提供出路；此前已能<strong>在体态生成纠缠态</strong>、<strong>在芯片上生成单光子态</strong>，但<strong>在芯片上生成纠缠斯格明子 + 可重构操控 + 与单光子斯格明子受控接口</strong>仍缺。</li><li>方法：<strong>集成氮化硅（Si₃N₄）纳米光子平台</strong>，在芯片上<strong>生成纠缠斯格明子并操控</strong>。</li><li>编码：斯格明子拓扑先被<strong>相干编码</strong>为<strong>局部单光子自旋纹理量子态</strong>，随后转移到<strong>两个纠缠光子共享的非局域拓扑</strong>。</li><li>关键结果：整个转移过程中<strong>拓扑在背景噪声与多种扰动下保持</strong>——<strong>甚至在纠缠消失后仍然保留</strong>。这是一个**&quot;超越纠缠&quot;的拓扑转移方案**，其抗噪韧性<strong>优于传统纠缠辅助的态转移</strong>。</li><li>意义：迈向<strong>鲁棒量子互联</strong>与<strong>以拓扑为中介的分布式量子信息</strong>技术。</li><li>洞察（对本库 <code>quantum-physics</code> / <code>physics</code>）：<strong>拓扑本身成了&quot;信息载体&quot;而不只是&quot;信息的属性&quot;</strong>——<strong>纠缠没了，拓扑还在</strong>。与 10-09 低对称石墨烯莫尔整流器（用<strong>对称性/拓扑</strong>工程物性）、10-10 中性原子纠缠门同属&quot;<strong>让量子信息更抗噪</strong>&quot;主线：<strong>把信息编码进全局几何量，比编码进局域态更稳。</strong></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/quantum-physics/index.md</code> ｜ 第36期 科学板块</p></blockquote><p>关键词：量子斯格明子、拓扑鲁棒性、光子斯格明子、纠缠斯格明子、自旋纹理量子态、非局域拓扑、集成氮化硅、Si₃N₄ 纳米光子学、纠缠辅助态转移、超越纠缠、量子互联、分布式量子信息 关联：<code>topics/quantum-physics/science-daily-2026-10-10.md</code>（中性原子 99.854% 纠缠门）、<code>topics/quantum-physics/science-daily-2026-10-09.md</code>（晶圆级低对称石墨烯量子整流器：对称性/拓扑工程）、<code>topics/quantum-physics/spacetime-mechanism-entanglement.md</code>（纠缠与拓扑的另一视角）</p>',9)])])}const m=o(r,[["render",c]]);export{p as __pageData,m as default};
